mapper.select:
select *
from pm_payment_order
where merchant_id = #{merchantId}
  and platform = #{platform}
  and payable_amount_minor = #{amountMinor}
  and status in ('PENDING', 'CONFLICT')
  and created_at <= #{eventTime}
  and expires_at + interval '120 seconds' >= #{eventTime}
order by created_at asc
for update

select * from pm_payment_order
where id = #{id} and merchant_id = #{merchantId}
for update
